"""Isolate AST traversal with 64 files containing 1000 ordinary calls each."""
from pathlib import Path
import argparse,hashlib,json,os,statistics,subprocess,sys,tempfile,time
area=Path(__file__).resolve().parent
sys.path.insert(0,str(Path.cwd()/'scripts'))
from benchmark import create_corpus
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--samples',type=int,default=21);p.add_argument('--profile-binary',type=Path);args=p.parse_args()
binaries={phase:area/f'{phase}-jscycles' for phase in ['before','after']}
timings={phase:[] for phase in binaries}
with tempfile.TemporaryDirectory(prefix='jscycles-dense-syntax-') as temporary:
 root=Path(temporary);_,extra,_,_=create_corpus(root,64,'call-heavy',1,1)
 for file in root.glob('module*.ts'):
  file.write_text(file.read_text()+'\n'+'\n'.join(f'Math.abs({number});' for number in range(12,1000)))
 fingerprint=hashlib.sha256()
 for file in sorted(root.rglob('*')):
  if file.is_file():fingerprint.update(str(file.relative_to(root)).encode()+b'\0'+file.read_bytes())
 arguments=[str(root),*extra,'--json'];expected=None
 def scan(binary,environment=None):
  result=subprocess.run([str(binary),*arguments],capture_output=True,timeout=60,env=environment)
  assert result.returncode==1 and not result.stderr,result.stderr
  report=json.loads(result.stdout);assert report['has_file_cycles'] and not report['has_package_cycles']
  assert sum(len(item['cycles']) for item in report['file_cycles'])==1
  return result.stdout
 if args.profile_binary:
  scan(args.profile_binary.resolve(),dict(os.environ,HOTPATH_OUTPUT_PATH=str(area/'dense-hotpath.json')))
  raise SystemExit(0)
 for sample in range(args.samples+1):
  order=list(binaries)
  if sample%2:order.reverse()
  for phase in order:
   start=time.perf_counter();stdout=scan(binaries[phase]);elapsed=time.perf_counter()-start
   if expected is None:expected=stdout
   assert stdout==expected
   if sample:timings[phase].append(elapsed)
report={'schema':1,'files':64,'ordinary_calls_per_file':1000,'samples':args.samples,'warmups':1,'corpus_sha256':fingerprint.hexdigest(),'outputs_equal':True,'order':'alternating saved normal binaries on the same corpus','binaries':{phase:{'sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'samples_seconds':timings[phase],'median_seconds':statistics.median(timings[phase])} for phase,binary in binaries.items()},'limits':'Warm synthetic AST-dense workload; not a customer budget or universal speedup.'}
(area/'dense-comparison.json').write_text(json.dumps(report,indent=2)+'\n')
print({phase:row['median_seconds'] for phase,row in report['binaries'].items()})
